<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { loadAtlasCatalog } from '../atlasCatalog';
import { errorText } from '../api';
import type { AtlasCatalog, PlaceInput } from '../../../packages/contracts/src/index.js';
const model = defineModel<PlaceInput | null>({ required: true }); const props = withDefaults(defineProps<{ label?: string }>(), { label: '城市归属' });
const catalog = ref<AtlasCatalog | null>(null), error = ref('');
const country = computed(() => model.value?.countryCode ?? 'CHN'), province = computed(() => catalog.value?.cities.find(c => c.code === model.value?.areaCode)?.provinceCode ?? model.value?.areaCode ?? ''), city = computed(() => model.value?.cityName !== undefined && country.value === 'CHN' ? 'custom' : catalog.value?.cities.some(c => c.code === model.value?.areaCode) ? model.value?.areaCode ?? '' : '');
const cities = computed(() => catalog.value?.cities.filter(c => c.provinceCode === province.value) ?? []);
async function load() { error.value = ''; try { catalog.value = await loadAtlasCatalog(); } catch (e) { error.value = errorText(e); } }
onMounted(load);
function setCountry(value: string) { model.value = value === 'CHN' ? null : { countryCode: value, cityName: '' }; }
function setProvince(value: string) { model.value = value ? { countryCode: 'CHN', areaCode: value } : null; }
function setCity(value: string) { model.value = value === 'custom' ? { countryCode: 'CHN', areaCode: province.value, cityName: '' } : { countryCode: 'CHN', areaCode: value || province.value }; }
</script>
<template><section class="place-picker"><p class="picker-heading">{{ props.label }}</p><p v-if="error" class="flow-form-errors">{{ error }}<button type="button" class="text-button" @click="load">重试地区目录</button></p><p v-else-if="!catalog" class="small muted">正在读取地区目录…</p><template v-if="catalog"><label class="flow-field"><span>国家／地区</span><select :value="country" aria-label="国家／地区" @change="setCountry(($event.target as HTMLSelectElement).value)"><option v-for="c in catalog.countries" :key="c.code" :value="c.code">{{ c.name }}</option></select></label><template v-if="country === 'CHN'"><div class="place-picker-grid"><label class="flow-field"><span>省级地区</span><select :value="province" aria-label="省级地区" @change="setProvince(($event.target as HTMLSelectElement).value)"><option value="">请选择，也可暂不归属</option><option v-for="p in catalog.provinces" :key="p.code" :value="p.code">{{ p.name }}</option></select></label><label v-if="cities.length" class="flow-field"><span>城市</span><select :value="city" aria-label="城市" @change="setCity(($event.target as HTMLSelectElement).value)"><option value="">仅记录省份</option><option value="custom">手工填写城市</option><option v-for="c in cities" :key="c.code" :value="c.code">{{ c.name }}</option></select></label></div><button v-if="province && !cities.length && city !== 'custom'" type="button" class="text-button" @click="setCity('custom')">手工补充城市名称</button><label v-if="city === 'custom'" class="flow-field"><span>城市名称</span><input :value="model?.cityName ?? ''" aria-label="手填城市名称" maxlength="80" placeholder="填写实际城市名称" @input="model = { countryCode: 'CHN', areaCode: province, cityName: ($event.target as HTMLInputElement).value }"><small>保留所选省份归属，不猜测城市坐标；相同写法汇总，之后可编辑。</small></label><p class="small muted">归属经你确认后点亮地图；仅选省份不会计入城市数。直辖市、香港和澳门按城市记录。</p></template><label v-else class="flow-field"><span>城市名称</span><input :value="model?.cityName ?? ''" aria-label="境外城市名称" maxlength="80" placeholder="如：东京" @input="model = { countryCode: country, cityName: ($event.target as HTMLInputElement).value }"><small>按填写的城市名称汇总；当前世界图点亮国家／地区，不猜测城市坐标。</small></label></template></section></template>
